describe('Google Account Connection', () => {
  beforeEach(() => {
    cy.visit('/profile');
    cy.get('[data-testid="profile-page"]').should('be.visible');
  });

  it('should successfully connect Google account to user profile', () => {
    cy.get('[data-testid="connect-google-btn"]').click();

    cy.origin('https://accounts.google.com', () => {
      cy.get('input[type="email"]').type('testuser@gmail.com');
      cy.get('#identifierNext').click();
      cy.get('input[type="password"]').type('testPassword123!');
      cy.get('#passwordNext').click();
    });

    cy.get('[data-testid="google-consent-allow"]').should('be.visible');
    cy.get('[data-testid="google-consent-allow"]').click();

    cy.get('[data-testid="success-message"]').should('contain', 'Google account connected successfully');
    cy.get('[data-testid="connected-account-email"]').should('contain', 'testuser@gmail.com');
    cy.get('[data-testid="disconnect-google-btn"]').should('be.visible');
  });

  it('should handle Google authentication cancellation gracefully', () => {
    cy.get('[data-testid="connect-google-btn"]').click();

    cy.origin('https://accounts.google.com', () => {
      cy.get('[data-testid="cancel-btn"]').click();
    });

    cy.get('[data-testid="connection-cancelled-message"]').should('contain', 'Connection cancelled');
    cy.get('[data-testid="connect-google-btn"]').should('be.visible');
    cy.get('[data-testid="connected-account-email"]').should('not.exist');
  });

  it('should prevent connecting multiple Google accounts', () => {
    cy.get('[data-testid="connected-account-email"]').should('contain', 'existing@gmail.com');
    cy.get('[data-testid="connect-google-btn"]').should('be.disabled');
    cy.get('[data-testid="connect-google-btn"]').should('have.attr', 'title', 'Google account already connected');
  });

  it('should display error when Google authentication fails', () => {
    cy.get('[data-testid="connect-google-btn"]').click();

    cy.origin('https://accounts.google.com', () => {
      cy.get('input[type="email"]').type('invalid@gmail.com');
      cy.get('#identifierNext').click();
      cy.get('[data-testid="error-message"]').should('contain', 'Account not found');
    });

    cy.get('[data-testid="auth-error-message"]').should('be.visible');
    cy.get('[data-testid="retry-connection-btn"]').should('be.visible');
  });

  it('should disconnect Google account and allow reconnection', () => {
    cy.get('[data-testid="connected-account-email"]').should('contain', 'testuser@gmail.com');
    cy.get('[data-testid="disconnect-google-btn"]').click();

    cy.get('[data-testid="disconnect-confirmation-modal"]').should('be.visible');
    cy.get('[data-testid="confirm-disconnect-btn"]').click();

    cy.get('[data-testid="disconnection-success-message"]').should('contain', 'Google account disconnected');
    cy.get('[data-testid="connect-google-btn"]').should('not.be.disabled');
    cy.get('[data-testid="connected-account-email"]').should('not.exist');
  });

  it('should persist Google account connection after page reload', () => {
    cy.get('[data-testid="connected-account-email"]').should('contain', 'testuser@gmail.com');
    cy.reload();

    cy.get('[data-testid="profile-page"]').should('be.visible');
    cy.get('[data-testid="connected-account-email"]').should('contain', 'testuser@gmail.com');
    cy.get('[data-testid="disconnect-google-btn"]').should('be.visible');
  });

  it('should handle network timeout during Google authentication', () => {
    cy.intercept('POST', '**/auth/google/callback', { 
      delay: 10000,
      statusCode: 504 
    }).as('googleAuthTimeout');

    cy.get('[data-testid="connect-google-btn"]').click();
    cy.wait('@googleAuthTimeout', { timeout: 12000 });

    cy.get('[data-testid="timeout-error-message"]').should('contain', 'Connection timeout');
    cy.get('[data-testid="retry-connection-btn"]').should('be.visible');
  });
});
